// 1. 模板方法基础结构
public abstract class AbstractClass {
    // 模板方法：final 锁死步骤顺序
    public final void templateMethod() {
        step1();
        step2();
        hookMethod();
    }
    // 抽象步骤：子类必须实现
    protected abstract void step1();
    protected abstract void step2();
    // 钩子方法：默认空实现，子类按需重写
    protected void hookMethod() { }
}

public class ConcreteClass extends AbstractClass {
    @Override
    protected void step1() {
        System.out.println("[ConcreteClass] step1");
    }
    @Override
    protected void step2() {
        System.out.println("[ConcreteClass] step2");
    }
    @Override
    protected void hookMethod() {
        System.out.println("[ConcreteClass] hookMethod 重写");
    }
}
// new ConcreteClass().templateMethod() 输出：
// [ConcreteClass] step1
// [ConcreteClass] step2
// [ConcreteClass] hookMethod 重写
// 证明：父类 templateMethod 控制了 step1→step2→hook 的顺序

// 2. AQS 模板方法（简化版，展示骨架与钩子关系）
public abstract class AbstractQueuedSynchronizer {
    // final 模板方法：锁死「尝试获取→失败入队→挂起」骨架
    public final void acquire(int arg) {
        if (!tryAcquire(arg) &&
            acquireQueued(addWaiter(Node.EXCLUSIVE), arg)) {
            selfInterrupt();
        }
    }
    // 钩子方法：默认抛异常，强制子类按语义实现
    protected boolean tryAcquire(int arg) {
        throw new UnsupportedOperationException();
    }
    protected boolean tryRelease(int arg) {
        throw new UnsupportedOperationException();
    }
}
// ReentrantLock.tryAcquire：CAS state 0→1，成功设持有线程
// Semaphore.tryAcquire：CAS state（许可数）减 1
// 同一 acquire 骨架，不同子类赋予不同同步语义

// 3. JdbcTemplate（回调式模板）
// 骨架固定：拿连接→执行→异常翻译→释放资源
// 可变部分由回调接口传入，比纯继承灵活
public class JdbcTemplate {
    public <T> T execute(ConnectionCallback<T> action)
            throws DataAccessException {
        Connection con = DataSourceUtils.getConnection(dataSource);
        try {
            return action.doInConnection(con);
        } catch (SQLException ex) {
            throw getExceptionTranslator()
                .translate("ConnectionCallback", getSql(action), ex);
        } finally {
            DataSourceUtils.releaseConnection(con, dataSource);
        }
    }
}
// 开发者只需实现 ConnectionCallback，不用管连接获取/释放

// 4. Spring AbstractApplicationContext.refresh() —— 12 步容器启动骨架
public abstract class AbstractApplicationContext {
    public void refresh() throws BeansException {
        prepareRefresh();                                  // 1. 标记 active、校验属性
        ConfigurableListableBeanFactory bf = obtainFreshBeanFactory(); // 2. 获取 BeanFactory
        prepareBeanFactory(bf);                            // 3. 配置 ClassLoader 等
        postProcessBeanFactory(bf);                        // 4. 钩子：子类额外配置
        invokeBeanFactoryPostProcessors(bf);               // 5. 执行 BFPP
        registerBeanPostProcessors(bf);                    // 6. 注册 BPP
        initMessageSource();                               // 7. 国际化
        initApplicationEventMulticaster();                 // 8. 事件广播器
        onRefresh();                                       // 9. 钩子：Spring Boot 在此启动 Tomcat
        registerListeners();                               // 10. 注册监听器
        finishBeanFactoryInitialization(bf);               // 11. 实例化所有非懒加载单例
        finishRefresh();                                   // 12. 发布 ContextRefreshedEvent
    }
}
